#!/usr/bin/env bash
# Generates docs/architecture/crates.d2 (the crate dependency view) from `cargo metadata`.
# Run through `just arch`; don't edit crates.d2 by hand.
set -euo pipefail

# Crates without I/O (CLAUDE.md: core is pure; han is a pure parser).
pure='["energybrain-core","energybrain-han"]'

cargo metadata --format-version 1 --no-deps | jq -r --argjson pure "$pure" '
  def id: sub("^energybrain-"; "") | if . == "energybrain" then "app" else . end;
  def internal: .name | startswith("energybrain");
  "# GENERATED by scripts/arch-crates.sh from `cargo metadata`; run `just arch`, do not edit.",
  "# Solid: normal dependency. Dashed: dev-dependency only. Box text: external dependencies.",
  "",
  "direction: down",
  "",
  "classes: {",
  "  pure: {style: {fill: \"#ecfdf5\"; stroke: \"#059669\"}}",
  "  io: {style: {fill: \"#eff6ff\"; stroke: \"#2563eb\"}}",
  "  dev: {style: {fill: \"#fff7ed\"; stroke: \"#ea580c\"; stroke-dash: 4}}",
  "}",
  "",
  (.packages | sort_by(.name)[] |
    (.name | id) as $id
    | ([.dependencies[] | select((internal | not) and .kind == null) | .name] | unique | join(" · ")) as $ext
    | .name as $n | (if ($pure | index($n)) then "pure" elif $n == "energybrain-sim" then "dev" else "io" end) as $class
    | "\($id): \"\(.name)\\n\($ext)\" {class: \($class)}"),
  "",
  (.packages | sort_by(.name)[] |
    (.name | id) as $from
    | [.dependencies[] | select(internal)] | group_by(.name)[]
    | (.[0].name | id) as $to
    | if any(.[]; .kind == null) then "\($from) -> \($to)"
      elif any(.[]; .kind == "dev") then "\($from) -> \($to): dev {style.stroke-dash: 4}"
      else empty end)
'
